#include "hostprof.h"
#include "mu_elf_bridge.h"
#include <cstdio>
#include <cstring>

extern "C" {
extern uint64_t mu_prof_stats[hostprof::kSlots][4];
extern void* mu_prof_orig[hostprof::kSlots];
extern uint64_t mu_prof_stack[64][4];
extern uint64_t* mu_prof_sp;
extern const uint32_t mu_prof_thunks[hostprof::kSlots][2];     // two instructions each
}
// Generated by build.sh from mu_host.h: the member names of both tables, in order.
extern const char* const mu_host_api_names[];
extern const int mu_host_api_name_count;
extern const char* const mu_game_api_names[];
extern const int mu_game_api_name_count;

namespace hostprof {
namespace {
constexpr int kGameBase = 100;          // host table: slots 0..94, game table: 100..110
bool is_installed = false;
const char* slot_names[kSlots];
char name_text[kSlots][48];

// Both tables are a 32-bit version followed by function pointers only (build.sh checks the counts).
void wrap(void* table, size_t size, int base, const char* const* names, int name_count, const char* prefix, int skip_first) {
  void** entries = reinterpret_cast<void**>(static_cast<char*>(table) + sizeof(void*));
  const int count = int(size / sizeof(void*)) - 1;
  for (int i = skip_first; i < count && base + i < kSlots; ++i) {
    if (!entries[i]) continue;
    mu_prof_orig[base + i] = entries[i];
    entries[i] = const_cast<void*>(static_cast<const void*>(mu_prof_thunks[base + i]));
    std::snprintf(name_text[base + i], sizeof name_text[0], "%s%s", prefix, i < name_count && count == name_count ? names[i] : "?");
    slot_names[base + i] = name_text[base + i];
  }
}
void hook(MuHostApi* host, MuGameApi* game) {
  if (host) wrap(host, sizeof *host, 0, mu_host_api_names, mu_host_api_name_count, "host ", 0);
  // The game's `run` is the whole simulation: left alone, it is what everything else is subtracted from.
  if (game) wrap(game, sizeof *game, kGameBase, mu_game_api_names, mu_game_api_name_count, "game ", 1);
}
} // namespace

void install() {
  mu_prof_sp = &mu_prof_stack[0][0];
  linux_host::set_tables_hook(hook);
  is_installed = true;
}
bool installed() { return is_installed; }
const char* name(int slot) { return slot >= 0 && slot < kSlots ? slot_names[slot] : nullptr; }
void read(Sample* out) {
  for (int i = 0; i < kSlots; ++i) { out->calls[i] = mu_prof_stats[i][0]; out->ticks[i] = mu_prof_stats[i][1]; }
}
uint64_t now() {
  uint64_t t;
#ifdef __SWITCH__
  __asm__ volatile("mrs %0, cntpct_el0" : "=r"(t));
#else
  __asm__ volatile("mrs %0, cntvct_el0" : "=r"(t));
#endif
  return t;
}
uint64_t frequency() { uint64_t f; __asm__ volatile("mrs %0, cntfrq_el0" : "=r"(f)); return f; }
void discount(uint64_t ticks) {
  if (!is_installed || mu_prof_sp == &mu_prof_stack[0][0]) return;
  mu_prof_sp[-1] += ticks;          // the running service's "nested" field
}
} // namespace hostprof
